    self:ReadAPRRoster()
    self:SetTimer(
        "rosterTimeout",
        10,

        --[[APR_DIAG]]
        APRTrace("APR-Core/features/group/PartyFinderWorld.lua:271:callback#14", --[[/APR_DIAG]] function()
            self.rosterLoading = nil
            self:CancelTimer("rosterReadTimer")
            self:RestoreAPRRosterSelection()
