            --[[APR_DIAG]]
            APRTrace(
                "APR-Core/features/group/PartyFinderWorld.lua:468:callback#24", --[[/APR_DIAG]]
                function() self:NextAPRBatch() end --[[APR_DIAG]]
            ) --[[/APR_DIAG]]
        )
        return
