    if wait > 0 then
        self:SetTimer(
            "sweepTimer",
            wait,

            --[[APR_DIAG]]
            APRTrace(
                "APR-Core/features/group/PartyFinderWorld.lua:483:callback#25", --[[/APR_DIAG]]
                function() self:SendNextAPRRequest() end --[[APR_DIAG]]
            ) --[[/APR_DIAG]]
        )
