function Finder:CandidateExpiry(data)
    if data.sweep then
        if self.sweep then return math.huge end
        return math.max(data.seenAt + 120, self.sweepRetainUntil or 0)
    end
    return data.seenAt + 120
end--[[APR_DIAG]]
